/*
    Program 07: Check whether real roots of a quadratic equation exist; if they exist, find them
    Topic: Conditional Statements + Math library
*/
#include <stdio.h>
#include <math.h>
#include "../projects.h"

void program07(void)
{
    float a, b, c, discriminant, root1, root2;

    printf("--- Program 07: Roots of a Quadratic Equation ---\n");
    printf("Enter coefficients a, b, c: ");
    scanf("%f %f %f", &a, &b, &c);

    if (a == 0)
    {
        printf("Coefficient 'a' cannot be 0 (not a quadratic equation)\n");
        return;
    }

    discriminant = b * b - 4 * a * c;

    if (discriminant >= 0)
    {
        printf("Real roots exist.\n");
        root1 = (-b + sqrt(discriminant)) / (2 * a);
        root2 = (-b - sqrt(discriminant)) / (2 * a);
        printf("Root 1 is: %.2f\nRoot 2 is: %.2f\n", root1, root2);
    }
    else
    {
        printf("No real roots exist (roots are complex/imaginary).\n");
    }
}

/*
    Program 08: Prime check - either a single number, or all primes in a range
    Topic: Loops + Functions
*/
#include <stdio.h>
#include "../projects.h"

static int check_prime(int num)
{
    int i;
    if (num <= 1)
        return 0;
    for (i = 2; i * i <= num; i++)
    {
        if (num % i == 0)
            return 0;
    }
    return 1;
}

void program08(void)
{
    int option;

    printf("--- Program 08: Prime Check ---\n");
    printf("1. Check a single number\n");
    printf("2. List primes in a range\n");
    printf("Enter your choice: ");
    scanf("%d", &option);

    if (option == 1)
    {
        int num;
        printf("Enter number: ");
        scanf("%d", &num);
        if (check_prime(num))
            printf("%d is a prime number\n", num);
        else
            printf("%d is not a prime number\n", num);
    }
    else if (option == 2)
    {
        int lower, higher, i;
        printf("Enter lower number: ");
        scanf("%d", &lower);
        printf("Enter higher number: ");
        scanf("%d", &higher);

        if (lower > higher)
        {
            printf("Lower number must not be greater than higher number.\n");
            return;
        }

        printf("Prime numbers between %d and %d:\n", lower, higher);
        for (i = lower; i <= higher; i++)
        {
            if (check_prime(i))
                printf("%d\n", i);
        }
    }
    else
    {
        printf("Invalid choice.\n");
    }
}

