/*
    Program 15: Find the factorial of a number using recursion
    Topic: Recursion
*/
#include <stdio.h>
#include "../projects.h"

static long fact(int num)
{
    if (num == 0 || num == 1)
        return 1;
    else
        return num * fact(num - 1);
}

