/*
    Program 24: Find a pair with a given sum in a sorted array
    Topic: Two Pointers
    (New - from the roadmap's "Two Pointers" node. One pointer starts
    at the beginning, one at the end; they move toward each other
    based on whether the current sum is too small or too large. This
    finds the pair in O(n) instead of checking every pair in O(n^2).)
*/
#include <stdio.h>
#include "../projects.h"

void program24(void)
{
    int arr[100];
    int n, i, target, left, right, sum;
    int found = 0;

    printf("--- Program 24: Two Pointers - Pair With Given Sum ---\n");
    printf("Enter number of elements: ");
    scanf("%d", &n);

    if (n <= 1 || n > 100)
    {
        printf("Please enter a size between 2 and 100.\n");
        return;
    }

    printf("Enter %d elements in ascending (sorted) order: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter target sum: ");
    scanf("%d", &target);

    left = 0;
    right = n - 1;

    while (left < right)
    {
        sum = arr[left] + arr[right];
        if (sum == target)
        {
            printf("Pair found: %d + %d = %d\n", arr[left], arr[right], target);
            found = 1;
            break;
        }
        else if (sum < target)
        {
            left++;
        }
        else
        {
            right--;
        }
    }

    if (!found)
        printf("No pair adds up to %d\n", target);
}

/*
    Program 25: Maximum sum subarray of size k (Sliding Window)
    Topic: Sliding Window
    (New - from the roadmap's "Sliding Window" node. Instead of
    recomputing the sum of every window of size k from scratch, we
    "slide" it: subtract the element leaving the window and add the
    element entering it. This turns an O(n*k) approach into O(n).)
*/
#include <stdio.h>
#include "../projects.h"

void program25(void)
{
    int arr[100];
    int n, k, i;
    int window_sum = 0, max_sum;

    printf("--- Program 25: Sliding Window - Max Sum Subarray of Size k ---\n");
    printf("Enter number of elements: ");
    scanf("%d", &n);

    if (n <= 0 || n > 100)
    {
        printf("Please enter a size between 1 and 100.\n");
        return;
    }

    printf("Enter %d elements: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter window size k: ");
    scanf("%d", &k);

    if (k <= 0 || k > n)
    {
        printf("k must be between 1 and %d.\n", n);
        return;
    }

    for (i = 0; i < k; i++)
        window_sum += arr[i];

    max_sum = window_sum;

    for (i = k; i < n; i++)
    {
        window_sum += arr[i] - arr[i - k];
        if (window_sum > max_sum)
            max_sum = window_sum;
    }

    printf("Maximum sum of a subarray of size %d is: %d\n", k, max_sum);
}

/*
    Program 26: Binary search for a target value in a sorted array
    Topic: Binary Search
    (New - from the roadmap's "Binary Search" node. Repeatedly checks
    the middle element and discards the half the target cannot be in,
    giving O(log n) instead of the O(n) of a linear scan.)
*/
#include <stdio.h>
#include "../projects.h"

void program26(void)
{
    int arr[100];
    int n, i, target, low, high, mid;
    int position = -1;

    printf("--- Program 26: Binary Search ---\n");
    printf("Enter number of elements: ");
    scanf("%d", &n);

    if (n <= 0 || n > 100)
    {
        printf("Please enter a size between 1 and 100.\n");
        return;
    }

    printf("Enter %d elements in ascending (sorted) order: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter target value: ");
    scanf("%d", &target);

    low = 0;
    high = n - 1;

    while (low <= high)
    {
        mid = (low + high) / 2;

        if (arr[mid] == target)
        {
            position = mid;
            break;
        }
        else if (arr[mid] < target)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    if (position != -1)
        printf("%d found at index %d\n", target, position);
    else
        printf("%d not found in the array\n", target);
}

/*
    Program 27: Array based Min-Heap - insert and extract-min
    Topic: Heap / Priority Queue
    (New - from the roadmap's "Heap / Priority Queue" node. A binary
    min-heap is stored in a plain array: for index i, its children are
    at 2*i+1 and 2*i+2. "Bubble up" fixes the heap after an insert,
    "bubble down" fixes it after removing the smallest element.)
*/
#include <stdio.h>
#include "../projects.h"

#define MAX_HEAP 100

static int heap[MAX_HEAP];
static int heap_size = 0;

static void swap_int(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

static void heap_insert(int value)
{
    int i;

    if (heap_size >= MAX_HEAP)
    {
        printf("Heap is full, cannot insert %d\n", value);
        return;
    }

    heap[heap_size] = value;
    i = heap_size;
    heap_size++;

    /* bubble up: while the new value is smaller than its parent, swap up */
    while (i > 0 && heap[(i - 1) / 2] > heap[i])
    {
        swap_int(&heap[(i - 1) / 2], &heap[i]);
        i = (i - 1) / 2;
    }
}

static int heap_extract_min(void)
{
    int min_value, i, smallest, left, right;

    if (heap_size == 0)
    {
        printf("Heap is empty\n");
        return -1;
    }

    min_value = heap[0];
    heap_size--;
    heap[0] = heap[heap_size];

    /* bubble down: repeatedly swap with the smaller child until placed */
    i = 0;
    for (;;)
    {
        smallest = i;
        left = 2 * i + 1;
        right = 2 * i + 2;

        if (left < heap_size && heap[left] < heap[smallest])
            smallest = left;
        if (right < heap_size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        swap_int(&heap[i], &heap[smallest]);
        i = smallest;
    }

    return min_value;
}

void program27(void)
{
    int n, i, value, choice;

    heap_size = 0;

    printf("--- Program 27: Min-Heap / Priority Queue ---\n");
    printf("How many numbers do you want to insert? ");
    scanf("%d", &n);

    if (n <= 0 || n > MAX_HEAP)
    {
        printf("Please enter a size between 1 and %d.\n", MAX_HEAP);
        return;
    }

    printf("Enter %d numbers: ", n);
    for (i = 0; i < n; i++)
    {
        scanf("%d", &value);
        heap_insert(value);
    }

    printf("1. Extract the minimum once\n");
    printf("2. Extract all (prints numbers in sorted order)\n");
    printf("Enter your choice: ");
    scanf("%d", &choice);

    if (choice == 1)
    {
        printf("Minimum extracted: %d\n", heap_extract_min());
    }
    else if (choice == 2)
    {
        printf("Extracted order: ");
        while (heap_size > 0)
            printf("%d ", heap_extract_min());
        printf("\n");
    }
    else
    {
        printf("Invalid choice.\n");
    }
}

/*
    Program 28: Print all permutations of a string
    Topic: Backtracking
    (New - from the roadmap's "Backtracking" node. Fix one character
    at the current position, recursively permute the rest, then swap
    back ("backtrack") before trying the next character in that
    position. This is the classic first backtracking example.)
*/
#include <stdio.h>
#include <string.h>
#include "../projects.h"

static void swap_char(char *a, char *b)
{
    char t = *a;
    *a = *b;
    *b = t;
}

static void permute(char *str, int start, int len)
{
    int i;

    if (start == len - 1)
    {
        printf("%s\n", str);
        return;
    }

    for (i = start; i < len; i++)
    {
        swap_char(&str[start], &str[i]);
        permute(str, start + 1, len);
        swap_char(&str[start], &str[i]);   /* backtrack: undo the swap */
    }
}

void program28(void)
{
    char str[10];

    printf("--- Program 28: Permutations of a String ---\n");
    printf("Enter a short string (max 9 characters): ");
    scanf("%9s", str);

    printf("All permutations:\n");
    permute(str, 0, (int)strlen(str));
}

/*
    Program 29: Activity selection - pick the maximum number of
                non-overlapping activities
    Topic: Greedy
    (New - from the roadmap's "Greedy" node. Sort activities by
    finish time, then always pick the next activity whose start time
    is not before the last selected activity's finish time. Picking
    the earliest finishing activity at each step is the "greedy
    choice" that provably gives the maximum count.)
*/
#include <stdio.h>
#include "../projects.h"

#define MAX_ACTIVITIES 50

void program29(void)
{
    int start[MAX_ACTIVITIES], finish[MAX_ACTIVITIES];
    int n, i, j, count;
    int last_finish;

    printf("--- Program 29: Activity Selection (Greedy) ---\n");
    printf("Enter number of activities: ");
    scanf("%d", &n);

    if (n <= 0 || n > MAX_ACTIVITIES)
    {
        printf("Please enter a size between 1 and %d.\n", MAX_ACTIVITIES);
        return;
    }

    printf("Enter start and finish time for each activity:\n");
    for (i = 0; i < n; i++)
    {
        printf("Activity %d (start finish): ", i + 1);
        scanf("%d %d", &start[i], &finish[i]);
    }

    /* simple bubble sort by finish time (small n, so this is fine) */
    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
            if (finish[j] > finish[j + 1])
            {
                int ts = start[j];  start[j] = start[j + 1];   start[j + 1] = ts;
                int tf = finish[j]; finish[j] = finish[j + 1]; finish[j + 1] = tf;
            }
        }
    }

    printf("Selected activities (start, finish): (%d, %d) ", start[0], finish[0]);
    last_finish = finish[0];
    count = 1;

    for (i = 1; i < n; i++)
    {
        if (start[i] >= last_finish)
        {
            printf("(%d, %d) ", start[i], finish[i]);
            last_finish = finish[i];
            count++;
        }
    }

    printf("\nMaximum number of non-overlapping activities: %d\n", count);
}

/*
    Program 30: Basic bitwise operations demo
    Topic: Bit Manipulation
    (New - from the roadmap's "Bit Manipulation" node. Shows the
    everyday tricks: checking even/odd with & instead of %, counting
    set bits, and swapping two numbers with XOR instead of a temp
    variable - contrast this with Programs 11-13.)
*/
#include <stdio.h>
#include "../projects.h"

static int count_set_bits(int num)
{
    int count = 0;
    unsigned int n = (unsigned int)num;

    while (n != 0)
    {
        count += (n & 1);   /* check the last bit */
        n = n >> 1;         /* shift right to check the next bit */
    }
    return count;
}

void program30(void)
{
    int num, a, b;

    printf("--- Program 30: Bit Manipulation ---\n");

    printf("Enter a number to check even/odd and count set bits: ");
    scanf("%d", &num);

    if ((num & 1) == 0)
        printf("%d is even (last bit is 0)\n", num);
    else
        printf("%d is odd (last bit is 1)\n", num);

    printf("Number of set bits (1s) in %d is: %d\n", num, count_set_bits(num));

    printf("\nEnter two numbers to swap using XOR: ");
    scanf("%d %d", &a, &b);
    printf("Before swapping: a = %d, b = %d\n", a, b);

    a = a ^ b;
    b = a ^ b;
    a = a ^ b;

    printf("After swapping : a = %d, b = %d\n", a, b);
}

/*
    Program 31: Merge overlapping intervals
    Topic: Intervals
    (New - from the roadmap's "Intervals" node. Sort the intervals by
    start time, then walk through them once: if the current interval
    starts before (or exactly when) the last merged one ends, merge
    them by extending the end; otherwise start a new merged interval.)
*/
#include <stdio.h>
#include "../projects.h"

#define MAX_INTERVALS 50

void program31(void)
{
    int start[MAX_INTERVALS], end[MAX_INTERVALS];
    int n, i, j;
    int merged_start[MAX_INTERVALS], merged_end[MAX_INTERVALS];
    int merged_count = 0;

    printf("--- Program 31: Merge Overlapping Intervals ---\n");
    printf("Enter number of intervals: ");
    scanf("%d", &n);

    if (n <= 0 || n > MAX_INTERVALS)
    {
        printf("Please enter a size between 1 and %d.\n", MAX_INTERVALS);
        return;
    }

    printf("Enter each interval as: start end\n");
    for (i = 0; i < n; i++)
        scanf("%d %d", &start[i], &end[i]);

    /* simple bubble sort by start time (small n, so this is fine) */
    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
            if (start[j] > start[j + 1])
            {
                int ts = start[j]; start[j] = start[j + 1]; start[j + 1] = ts;
                int te = end[j];   end[j] = end[j + 1];     end[j + 1] = te;
            }
        }
    }

    merged_start[0] = start[0];
    merged_end[0] = end[0];
    merged_count = 1;

    for (i = 1; i < n; i++)
    {
        if (start[i] <= merged_end[merged_count - 1])
        {
            /* overlaps the last merged interval: extend it if needed */
            if (end[i] > merged_end[merged_count - 1])
                merged_end[merged_count - 1] = end[i];
        }
        else
        {
            merged_start[merged_count] = start[i];
            merged_end[merged_count] = end[i];
            merged_count++;
        }
    }

    printf("Merged intervals: ");
    for (i = 0; i < merged_count; i++)
        printf("[%d, %d] ", merged_start[i], merged_end[i]);
    printf("\n");
}

/*
    Program 32: Climbing stairs - count the number of distinct ways
                to climb n stairs, taking 1 or 2 steps at a time
    Topic: Dynamic Programming (1-D)
    (New - from the roadmap's "1-D Dynamic Programming" node. This is
    the same recurrence as Fibonacci (Program 16), but framed and
    solved bottom-up with a DP array: ways[i] = ways[i-1] + ways[i-2],
    since the last step taken to reach stair i was either 1 or 2.)
*/
#include <stdio.h>
#include "../projects.h"

void program32(void)
{
    int n, i;
    int ways[100];

    printf("--- Program 32: Climbing Stairs (1-D DP) ---\n");
    printf("Enter number of stairs: ");
    scanf("%d", &n);

    if (n < 0 || n > 99)
    {
        printf("Please enter a value between 0 and 99.\n");
        return;
    }

    if (n == 0)
    {
        printf("Number of distinct ways: 1\n");
        return;
    }

    ways[1] = 1;
    if (n >= 2)
        ways[2] = 2;

    for (i = 3; i <= n; i++)
        ways[i] = ways[i - 1] + ways[i - 2];

    printf("Number of distinct ways to climb %d stairs: %d\n", n, ways[n]);
}
